package com.procurement.invoice.entity;import com.procurement.purchaseorder.entity.PurchaseOrder;import com.procurement.goodsreceipt.entity.GoodsReceiptNote;import com.procurement.vendor.entity.Vendor;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.*;@Entity@Table(name="invoices",uniqueConstraints=@UniqueConstraint(columnNames="vendor_invoice_number"))@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class Invoice{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="invoice_id")private Long id;@Column(name="invoice_number",nullable=false,unique=true)private String invoiceNumber;@Column(name="vendor_invoice_number",nullable=false)private String vendorInvoiceNumber;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="purchase_order_id",nullable=false)private PurchaseOrder purchaseOrder;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="goods_receipt_note_id",nullable=false)private GoodsReceiptNote goodsReceiptNote;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="vendor_id",nullable=false)private Vendor vendor;@Column(nullable=false)private LocalDate invoiceDate;@Column(nullable=false)private LocalDate receivedDate;@Column(nullable=false)private LocalDate dueDate;@Column(nullable=false,length=3)private String currency;@Column(nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal subtotal=BigDecimal.ZERO;@Column(name="discount_amount",nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal discountAmount=BigDecimal.ZERO;@Column(name="tax_amount",nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal taxAmount=BigDecimal.ZERO;@Column(name="shipping_charges",nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal shippingCharges=BigDecimal.ZERO;@Column(name="other_charges",nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal otherCharges=BigDecimal.ZERO;@Column(name="grand_total",nullable=false,precision=15,scale=2)@Builder.Default private BigDecimal grandTotal=BigDecimal.ZERO;@Column(name="payment_terms")private String paymentTerms;@Column(name="payment_method")private String paymentMethod;@Column(length=1000)private String remarks;@Enumerated(EnumType.STRING)@Column(nullable=false,length=25)private InvoiceStatus status;@Column(name="created_by")private String createdBy;@Column(name="updated_by")private String updatedBy;@Column(name="created_at",updatable=false)private LocalDateTime createdAt;@Column(name="updated_at")private LocalDateTime updatedAt;@PrePersist void pre(){var n=LocalDateTime.now();createdAt=n;updatedAt=n;if(status==null)status=InvoiceStatus.DRAFT;}@PreUpdate void upd(){updatedAt=LocalDateTime.now();}}
